 * after next() returned false -- is an error.
 */
class FakeCursor {
    private final String[] names;
    private final int[] ages;
    private int index = -1;

    FakeCursor(String[] names, int[] ages) {
        this.names = names;
        this.ages = ages;
    }

    boolean next() {
        if (index < names.length) {
            index++;
        }
        return index < names.length;
    }

    String getString(String column) {
        checkPosition();
        if (!"name".equals(column)) {
            throw new IllegalArgumentException("no such string column: " + column);
        }
        return names[index];
    }

    int getInt(String column) {
        checkPosition();
        if (!"age".equals(column)) {
            throw new IllegalArgumentException("no such int column: " + column);
        }
        return ages[index];
    }

    private void checkPosition() {
        if (index < 0 || index >= names.length) {
            throw new IllegalStateException("cursor is not on a row");
        }
    }
}

