public class ResultCursorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static FakeCursor three() {
        return new FakeCursor(new String[] {"Ada", "Bo", "Cy"}, new int[] {36, 4, 5});
    }

    static FakeCursor empty() {
        return new FakeCursor(new String[] {}, new int[] {});
    }

    public static void main(String[] args) {
        try {
            check("collectNames three rows", "[Ada, Bo, Cy]", String.valueOf(ResultCursor.collectNames(three())));
            check("count three rows", 3, ResultCursor.count(three()));
            check("collectNames empty cursor", "[]", String.valueOf(ResultCursor.collectNames(empty())));
            check("count empty cursor", 0, ResultCursor.count(empty()));

            FakeCursor one = new FakeCursor(new String[] {"Solo"}, new int[] {1});
            check("collectNames single row", "[Solo]", String.valueOf(ResultCursor.collectNames(one)));

            FakeCursor drained = three();
            ResultCursor.collectNames(drained);
            check("count on an already drained cursor", 0, ResultCursor.count(drained));

            FakeCursor five = new FakeCursor(new String[] {"a", "b", "c", "d", "e"}, new int[] {1, 2, 3, 4, 5});
            check("count five rows", 5, ResultCursor.count(five));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

