public class ResultCursor {

    public static java.util.List<String> collectNames(FakeCursor c) {
        java.util.List<String> names = new java.util.ArrayList<>();
        while (c.next()) {
            names.add(c.getString("name"));
        }
        return names;
    }

    public static int count(FakeCursor c) {
        int rows = 0;
        while (c.next()) {
            rows++;
        }
        return rows;
    }
}
